const all = $input.all();
const rows = [];
for (let i = 0; i < all.length; i++) {
  const item = all[i].json;
  if (item && item.source) { rows.push(item); }
}
rows.sort(function(a, b) { return (b.score || 0) - (a.score || 0); });
const top = rows.slice(0, 10);
const lines = [
  "📊 DAILY TECH TRENDS | size=14 weight=bold color=#000000",
  "---",
  "⭐ TOP DISCOVERIES | size=12 weight=bold color=#FF4500"
];
if (top.length === 0) {
  lines.push("No data yet — run the Tech Trends Collector workflow first | size=13 color=#aaaaaa");
} else {
  for (let i = 0; i < top.length; i++) {
    const t = top[i];
    const title = (t.title || "Untitled").replace(/|/g, "-");
    lines.push((i + 1) + ". " + title + " | size=13 color=white");
  }
}
lines.push("---");
lines.push("ℹ️ System Details | size=11 color=#aaaaaa");
lines.push("• Powered by n8n | size=11 color=#aaaaaa");
return [{ json: { output: JSON.stringify(lines) } }];
